<?php
/**
 * QPOS high-contrast Slim receipt theme installer.
 * Delete this file immediately after a successful installation.
 */

declare(strict_types=1);

header('Content-Type: text/html; charset=UTF-8');

function qposEscape(string $value): string
{
    return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

function qposFail(string $message, int $status = 500): void
{
    http_response_code($status);
    echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>QPOS Slim Receipt Installer</title>';
    echo '<style>body{font:16px/1.55 system-ui,sans-serif;max-width:850px;margin:48px auto;padding:0 22px;color:#18181b}';
    echo '.box{border:3px solid #991b1b;background:#fff7f7;padding:24px;border-radius:10px}code{background:#eee;padding:2px 5px}</style></head><body>';
    echo '<div class="box"><h1>Installation stopped</h1><p>' . qposEscape($message) . '</p></div></body></html>';
    exit;
}

$providedKey = isset($_GET['key']) && is_string($_GET['key']) ? $_GET['key'] : '';
if (!hash_equals('qposclear2026', $providedKey)) {
    qposFail('Invalid or missing installer key.', 403);
}

$payloads = array (
  'resources/views/sale_pos/receipts/slim.blade.php' => 
  array (
    'sha1' => 'e5f83dad159e50ab5062aa9549890ecc6afab404',
    'base64' => '',
  ),
  'resources/views/sale_pos/partials/show_invoice.blade.php' => 
  array (
    'sha1' => '47f5b55a874598ddce5cbf8233895d0757f7b0c0',
    'base64' => '',
  ),
);

// The installer may be in Laravel's public/ directory or in a webroot
// containing the Laravel application itself.
$candidates = [__DIR__, dirname(__DIR__)];
$laravelRoot = null;
foreach (array_unique($candidates) as $candidate) {
    if (is_dir($candidate . '/resources/views') && is_dir($candidate . '/storage/framework/views')) {
        $laravelRoot = $candidate;
        break;
    }
}
if ($laravelRoot === null) {
    qposFail('Laravel root was not found. Place this installer beside the public index.php, with the application in that directory or its parent.');
}

$written = [];
$backups = [];
$stamp = date('Ymd-His');

foreach ($payloads as $relativePath => $payload) {
    $decoded = base64_decode($payload['base64'], true);
    if ($decoded === false || !hash_equals($payload['sha1'], sha1($decoded))) {
        qposFail('Embedded payload validation failed for ' . $relativePath . '.');
    }

    $destination = $laravelRoot . '/' . $relativePath;
    $directory = dirname($destination);
    if (!is_dir($directory) || !is_writable($directory)) {
        qposFail('Destination directory is missing or not writable: ' . $directory);
    }

    $mode = file_exists($destination) ? (fileperms($destination) & 0777) : 0644;
    if (file_exists($destination)) {
        $backup = $destination . '.bak-' . $stamp;
        $suffix = 1;
        while (file_exists($backup)) {
            $backup = $destination . '.bak-' . $stamp . '-' . $suffix++;
        }
        if (!copy($destination, $backup)) {
            qposFail('Could not create backup: ' . $backup);
        }
        $backups[] = $backup;
    }

    $temporary = $destination . '.qpos-tmp-' . bin2hex(random_bytes(6));
    if (file_put_contents($temporary, $decoded, LOCK_EX) !== strlen($decoded)) {
        @unlink($temporary);
        qposFail('Could not write temporary file for ' . $relativePath . '.');
    }
    @chmod($temporary, $mode);
    if (!rename($temporary, $destination)) {
        @unlink($temporary);
        qposFail('Could not replace ' . $relativePath . '.');
    }
    clearstatcache(true, $destination);
    if (!hash_equals($payload['sha1'], sha1_file($destination) ?: '')) {
        qposFail('Written file verification failed for ' . $relativePath . '. Restore its backup if necessary.');
    }
    if (function_exists('opcache_invalidate')) {
        @opcache_invalidate($destination, true);
    }
    $written[] = $relativePath;
}

$cleared = 0;
$compiledViews = glob($laravelRoot . '/storage/framework/views/*.php');
if (is_array($compiledViews)) {
    foreach ($compiledViews as $compiledView) {
        if (is_file($compiledView) && @unlink($compiledView)) {
            $cleared++;
        }
    }
}
$opcacheReset = function_exists('opcache_reset') ? @opcache_reset() : null;

?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>QPOS Slim Receipt Theme Installed</title>
<style>
body{font:17px/1.55 system-ui,-apple-system,sans-serif;max-width:900px;margin:42px auto;padding:0 22px;color:#111;background:#f4f4f5}
.panel{background:#fff;border:4px solid #111;border-radius:12px;padding:28px;box-shadow:8px 8px 0 #111}
h1{margin-top:0}.ok{color:#065f46;font-weight:800}.warn{border:3px solid #b45309;background:#fffbeb;padding:16px;margin-top:24px;font-weight:700}
li{margin:9px 0}code{background:#e4e4e7;padding:2px 6px;overflow-wrap:anywhere}
</style>
</head>
<body><main class="panel">
<h1>QPOS Slim Receipt Theme Installed</h1>
<p class="ok">Success: the high-contrast Slim receipt theme is now installed.</p>
<h2>Checklist</h2>
<ul>
<li>✓ Laravel root detected: <code><?= qposEscape($laravelRoot) ?></code></li>
<?php foreach ($written as $file): ?><li>✓ Written and SHA1 verified: <code><?= qposEscape($file) ?></code></li><?php endforeach; ?>
<li>✓ Backups created: <?= count($backups) ?></li>
<li>✓ Compiled Blade view files cleared: <?= $cleared ?></li>
<li>✓ OPcache invalidation requested for written files.</li>
<li>✓ OPcache reset <?= $opcacheReset === null ? 'was unavailable' : ($opcacheReset ? 'completed' : 'was requested but not confirmed') ?>.</li>
</ul>
<?php if ($backups): ?><h2>Backups</h2><ul><?php foreach ($backups as $backup): ?><li><code><?= qposEscape($backup) ?></code></li><?php endforeach; ?></ul><?php endif; ?>
<div class="warn">Security step: delete <code><?= qposEscape(basename(__FILE__)) ?></code> from the server now, then hard-refresh the browser.</div>
</main></body></html>